      ...(values.verbose ? { verbose: true } : {}),
      ...(values.runner ? { runner: values.runner as 'ao' | 'direct' } : {}),
      ...(values.harness ? { harnessChoice: values.harness as 'claude-code' | 'codex' | 'mixed' } : {}),
      ...(values['model-access-fallback-tier'] === undefined ? {} : { modelAccessFallbackTier: values['model-access-fallback-tier'] }),
      ...(values['allow-claude'] ? { allowClaude: true } : {}),
      ...(Object.keys(integrations).length ? { integrations } : {}),
      ...(repeats === undefined ? {} : { repeats }),
      loginTarget: name === 'login' ? 'cfoai' : undefined,
      output: values.output,
      limit,
      keyword: values.keyword,
      ...(values.replay === undefined ? {} : { replay: values.replay }),
      ...(values.review === undefined ? {} : { review: values.review }),
      ...(maxCredits === undefined ? {} : { maxCredits }),
      ...(values.jobs ? { jobs: true } : {}),
      ...(values.secondary === undefined ? {} : { secondary: values.secondary }),
      ...(values.out !== undefined ? { out: values.out } : {}),
      ...(values.runs !== undefined ? { runs: values.runs.split(',') } : {}),
      ...(values.run !== undefined ? { runId: values.run } : {}),
    },
  };
}

type Handler = (options: CliOptions, io: CliIO) => Promise<number>;

async function runCommand(options: CliOptions, io: CliIO): Promise<number> {
  let dashboard: DashboardServer | undefined;
  let interrupted: string | null = null;
  const interrupt = () => { interrupted = 'interrupted by user; workers stopped'; };
  try {
    if (options.plan) {
      const config = loadConfig(options.config);
      const budget = await readPlanBudget(config, { budgetUsd: options.budgetUsd });
      printBudget({ source: budget.source, limitSource: budget.limitSource, limitNanos: budget.limitNanos, spentNanos: 0,
        monthly: { source: budget.source, limitNanos: budget.monthlyLimitNanos, spentBeforeRunNanos: budget.monthlySpentNanos } }, io);
      if (budget.warning) io.stdout(`Budget note: ${budget.warning}`);
      io.stdout('Planning tasks. Enabled history reads are bounded. No workers will start.');
      const plan = await planTally({
        configPath: options.config,
        dryRun: options.dryRun,
        baseline: options.baseline,
        budgetUsd: options.budgetUsd,
        only: options.only,
        budgetInfo: budget,
      });
      if (plan.length === 0) {
        if (options.only) io.stdout(`No task matched --only ${JSON.stringify(options.only)}; nothing would start.`);
        else if (config.backlog.source === 'github-issues') {
          const label = config.backlog.issueLabel ?? 'tally';
          const repo = config.repo.slug ?? config.repo.path;
          io.stdout(`No runnable open issues with label ${JSON.stringify(label)} in ${repo}; nothing would start. Issues already linked to open PRs are excluded. Check the label and backlog before starting a run.`);
        } else {
          io.stdout(`No tasks found in the configured file backlog${config.backlog.file ? ` ${JSON.stringify(config.backlog.file)}` : ''}; nothing would start.`);
        }
      }
      for (const task of plan) {
        const route = task.skipped
          ? 'skip'
          : `${task.tier} ${task.harness}/${task.model} ceiling ${task.ceilingNanos === null ? 'none' : formatUsd(task.ceilingNanos)}`;
        io.stdout(`${task.taskId}: ${task.size} (confidence ${task.confidence.toFixed(2)}) -> ${route}`);
        const historySources = task.historySources.map((source) => {
          if (source === 'neatlogs') return 'remote Neatlogs';
          if (source === 'local') return config.integrations.neatlogs ? 'local Neatlogs fallback' : 'local history';
          return 'none';
        });
        io.stdout(`  History source: ${historySources.join(', ')}`);
        if (task.entire) printPlanText(`Entire: ${task.entire.status === 'ok' ? 'connected' : 'setup needed'}`, task.entire.detail ?? 'Graph sizing available and used.', io);
        if (task.historyDetail) printPlanText('History note', task.historyDetail, io);
        printPlanText('Decision', task.decision, io);
      }
      return 0;
    }
    if (options.dashboard) dashboard = await launchDashboard(options, io);
    process.on('SIGINT', interrupt);
    process.on('SIGTERM', interrupt);
    const result = await runTally({
      configPath: options.config,
      dryRun: options.dryRun,
      baseline: options.baseline,
      budgetUsd: options.budgetUsd,
      only: options.only,
      parallel: options.parallel,
      stopRequested: () => interrupted,
      onEvent: progressPrinter(io),
    });
    io.stdout(`wrote ${result.runStatePath}`);
    io.stdout(`wrote ${result.ledgerPath}`);
    io.stdout(`updated ${result.latestRunDir}`);
    io.stdout(`finished ${result.runState.runId}: ${result.runState.tasks.length} tasks, ${result.ledger.length} attempts`);
    if (result.runState.tasks.length === 0 && result.runState.backlog?.source === 'github-issues') {
      const label = result.runState.backlog.issueLabel ?? 'tally';
      const quote = (value: string) => `'${value.replace(/'/g, "'\\''")}'`;
      io.stdout(`No runnable open issues with label ${JSON.stringify(label)} in ${result.runState.repo}; nothing started. Issues already linked to open PRs are excluded. Label an issue with: gh issue edit <issue-number> --repo ${quote(result.runState.repo)} --add-label ${quote(label)}`);
    }
    printIntegrations(result, io);
    printRunSummary(result, io, dashboard?.url);
    process.off('SIGINT', interrupt);
    process.off('SIGTERM', interrupt);
    if (interrupted) { await dashboard?.close(); return 130; }
    if (dashboard) await waitForDashboard(dashboard);
    return 0;
  } catch (e) {
    await dashboard?.close();
    harness: 'entire',
    sessionId: input.previous.sessionId,
    entireSessionId: input.previous.entireSessionId ?? null,
    branch: input.previous.branch,
    tokens: input.decision.handoffSummaryTokens,
    estimatedCostNanos: input.decision.handoffSummaryCostNanos,
    costSource: input.decision.handoffSummaryCostSource,
    priceNote: 'Unverified: Entire-generated summary cost reported by the handoff adapter; no model list price supplied.',
    ceilingNanos: 0,
    result: 'passed',
    resultReason: 'Entire checkpoint summary generated for escalation',
    escalatedFrom: input.previous.attemptId,
    handoff: 'entire-handoff',
    prUrl: null,
    traceId: input.traceId,
    traceUrl: null,
    checkpointId: input.decision.checkpointId,
    checkpointUrl: input.decision.checkpointUrl,
    decision: `Entire generated a checkpoint handoff summary for ${input.task.taskId} before escalation.`,
    startedAt: timestamp,
    endedAt: timestamp,
  };
}

export async function runRealTally(options: RealRunOptions): Promise<RunResult> {
  const config = loadConfig(options.configPath);
  const requestedConcurrency = options.parallel ?? config.parallelWorkers ?? 1;
  if (!Number.isInteger(requestedConcurrency) || requestedConcurrency < 1) throw new Error('parallel worker count must be a positive integer');
  if (config.runner === 'direct' && options.parallel !== undefined && options.parallel > 1) throw new Error('parallel workers require runner ao; direct remains sequential');
  const concurrency = config.runner === 'direct' || options.baseline ? 1 : requestedConcurrency;
  let safetyStop: string | null = null;
  const stopRequested = () => safetyStop ?? options.stopRequested?.() ?? null;
  if (options.baseline && (options.parallel ?? 1) > 1) throw new Error('parallel AO workers require per-attempt ceilings; baseline remains sequential');
  if (concurrency > 1 && config.entire?.generatedSummaries) throw new Error('parallel workers require metadata-only handoffs; generated summary cost cannot be reserved');
  const ports = resolvePorts(config, options.configPath, options.ports, options.requiredBaseCommit);
  const now = options.now ?? (() => new Date());
  const started = now();
  const runId = options.runId ?? runIdFrom(started);
  const mode: RunMode = options.baseline ? 'baseline' : 'tally';
  const outputDir = options.outputDir ? resolve(options.outputDir) : defaultOutputDir(runId);
  const ledgerPath = resolve(outputDir, 'ledger.json');
  const ledger = loadLedger(ledgerPath);
  let budgetLimitNanos = usdToNanos(options.budgetUsd ?? config.budget.usd);
  let budgetSource: BudgetSource = 'config';
  let monthlyLimitNanos = usdToNanos(config.budget.usd);
  let monthlySpentNanos = 0;
  let cfoaiWriteFailure: string | null = null;
  const cfoaiContextFailures: string[] = [];
  let cfoaiReadFailure: string | null = null;
  let committedBeforeRunNanos = 0;
  if ((config.integrations.cfoai || config.budget.source === 'cfoai') && ports.cfoai) {
    try {
      const [limit, currentSpend] = await Promise.all([ports.cfoai.budgetLimitNanos(), ports.cfoai.currentSpendNanos?.() ?? Promise.resolve(0)]);
      monthlyLimitNanos = limit;
      monthlySpentNanos = currentSpend;
      budgetSource = 'cfoai';
      if (options.budgetUsd === undefined && config.budget.source === 'cfoai') {
        budgetLimitNanos = limit;
        committedBeforeRunNanos = Math.max(0, currentSpend - ledgerSpend(ledger));
      }
    } catch (error) {
      cfoaiReadFailure = error instanceof Error ? error.message : String(error);
      if (concurrency > 1 && !options.dryRun) throw new RunError([`parallel AO run cannot reserve the monthly budget: cfo.ai read failed: ${error instanceof Error ? error.message : String(error)}; no workers were started. Restore cfo.ai access or run sequentially with --parallel 1.`]);
      budgetSource = 'config';
    }
  }
  const monthlyCommittedBeforeRun = Math.max(0, monthlySpentNanos - ledgerSpend(ledger));
  // The sequential path must honor the same live CFO remainder as the parallel
  // reservations. A CLI cap can only tighten the cap, never bypass it.
  const availableRunLimitNanos = Math.max(0, Math.min(
    budgetLimitNanos - committedBeforeRunNanos,
    monthlyLimitNanos - monthlyCommittedBeforeRun,
  ));
  const ledgerBudget = new LedgerBudget(availableRunLimitNanos, ledger);
  const reservations = new Reservations(() => availableRunLimitNanos - ledgerSpend(ledger));
  const decisions = new SerialQueue();
  const accounting = new SerialQueue();
  const pendingCfoaiContexts: Array<{ row: LedgerRow; runSpentNanos: number; spendTableWriteStatus: 'ok' | 'failed' }> = [];
  const tasks = (await ports.intake.tasks(config, options.configPath)).filter((task) => {
    if (options.only === undefined) return true;
    return task.taskId === options.only || String(task.issueNumber) === options.only;
  });
  const savedRun = existsSync(resolve(outputDir, 'run.json')) ? JSON.parse(readFileSync(resolve(outputDir, 'run.json'), 'utf8')) as RunState : null;
  const resolvedBase = options.requiredBaseCommit !== undefined || (!savedRun?.baseCommit && !options.dryRun)
    ? await ports.worktrees.commitFor?.(resolve(dirname(options.configPath), config.repo.path), config.repo.baseBranch).catch(() => null) ?? null
    : null;
  if (options.requiredBaseCommit !== undefined) {
    if (resolvedBase !== options.requiredBaseCommit) {
      throw new Error(`Required base commit ${options.requiredBaseCommit} does not match resolved ${config.repo.baseBranch} base ${resolvedBase ?? '(unavailable)'}; no workers were started.`);
    }
    if (savedRun?.baseCommit && savedRun.baseCommit !== options.requiredBaseCommit) {
      throw new Error(`Saved run base ${savedRun.baseCommit} does not match required base commit ${options.requiredBaseCommit}; no workers were started.`);
    }
